/// <summary>
/// Finds the <C>METPurchTable</C> record based on record ID of <C>PurchTable</C> record.
/// </summary>
/// <param name="_purchTableRecId">
/// The record ID of <C>PurchTable</C> record.
/// </param>
/// <param name="_forUpdate">
/// A Boolean value that indicates whether to read the record for update; optional.
/// </param>
/// <returns>
/// A <C>METPurchTable</C> record.
/// </returns>
public static METPurchTable findByPurchTable(RefRecId _purchTableRecId, boolean _forUpdate = false)
{
    METPurchTable   METPurchTable;

    METPurchTable.SysExtensionSerializerExtensionMap::loadByBase(_purchTableRecId, _forUpdate);

    return METPurchTable;
}

    /// <summary>
    /// To initialize table buffer
    /// </summary>
    Public void initFromVendSiteSettingsSetup()
    {
        PurchTable purchTable = purchTable::findRecId(this.PurchTable);

        if(purchTable)
        {
            this.PurchId                               = purchTable.PurchId;
            this.POBackOrderSetting                    = purchtable.getVendSiteSettingsSetupFieldValues(fieldNum(METVendSiteSettingsSetup,DefaultBackOrderSetting));
            this.POExpressReceiptSetting               = purchtable.getVendSiteSettingsSetupFieldValues(fieldNum(METVendSiteSettingsSetup,ExpressReceiptSetting));
            this.POASNSetting                          = purchtable.getVendSiteSettingsSetupFieldValues(fieldNum(METVendSiteSettingsSetup,ASNSetting));
            this.POMinimumOrderValue                   = purchtable.getVendSiteSettingsSetupFieldValues(fieldNum(METVendSiteSettingsSetup,MinOrderVal));
            this.POSubMode                             = purchtable.getVendSiteSettingsSetupFieldValues(fieldNum(METVendSiteSettingsSetup,POSubMode));
            //MPJ_27166_BUYPOFSDEnhancements
            this.POChngSubMode                         = purchtable.getVendSiteSettingsSetupFieldValues(fieldNum(METVendSiteSettingsSetup,POChngSubMode));
        }

        if(METVendParameters::find().IGHPOHeadEmailEDIAutoDefConfirmOverride)//MPJ-28341-enhancements v3 IHG edi and change fields based on parameter is not working
        {
            this.POIHGEmailEDIAddress                  = purchtable.getVendSiteSettingsSetupEmailEDI();                  

            this.POIHGEmailEDIAddressChnge             = purchtable.getVendSiteSettingsSetupEmailChnge();
        }
        //MPJ_27166_BUYPOFSDEnhancements

    }

/// <summary>
/// MPJ_27166_BuyPOFSDEnhancements
/// MPJ-28299 - PO GAINS to D365 - EDI address / IHG email address not derived from Vendor.site
/// </summary>
public void insert()
{
    this.initFromVendSiteSettingsSetup();
            
    super();
}

/// <summary>
/// MPJ_27166_BuyPOFSDEnhancements
/// MPJ-28341-enhancements v3 IHG edi and change fields based on parameter is not working
/// </summary>
/// <param name = "_fieldId">Field id</param>
public void modifiedField(FieldId _fieldId)
{        
    super(_fieldId);
    if(METVendParameters::find().IGHPOHeadEmailEDIAutoDefConfirmOverride)
    {
        PurchTable purchTable = purchTable::findRecId(this.PurchTable);
        switch(_fieldId)
        {
        
            case fieldNum(METPurchTable,POSubMode):
                this.POIHGEmailEDIAddress                  = purchtable.getVendSiteSettingsSetupEmailEDI();
                this.write();
                break;
            case fieldNum(METPurchTable,POChngSubMode):
                this.POIHGEmailEDIAddressChnge             = purchtable.getVendSiteSettingsSetupEmailChnge();
                this.write();
                break;
        }
    }
}

/// <summary>
/// MPJ_19962_MDRPOTransactionalMissingFields kavya
/// </summary>
/// <returns>boolean value</returns>
public boolean validateWrite()
{
    boolean ret;

    ret = super();

    return ret;
}

    /// <summary>
    /// Finds the specified record in the <c>METInventTable</c> table.
    /// </summary>
    /// <param name="_purchId">
    /// The purchId of the <c>METPurchTable</c> record to find.
    /// </param>
    /// <param name="_update">
    /// A Boolean value that indicates whether to read the record for update; optional.
    /// </param>
    /// <returns>
    /// A record in the <c>METPurchTable</c> table; otherwise, an empty record.
    /// </returns>
    public static METPurchTable find(PurchId      _purchId,
                                     boolean     _update = false)
    {
        METPurchTable  metPurchTable;

        metPurchTable.selectForUpdate(_update);

        if (_purchId)
        {
            select firstonly metPurchTable
                where metPurchTable.PurchId == _purchId;
        }

        return metPurchTable;
    }

/// <summary>
/// MPJ_30715 Purchase Order Cancel 30/08/2022
/// </summary>
public void update()
{
    if(!this.PurchId)
    {
        this.purchId = PurchTable::findRecId(this.PurchTable).PurchId;
    }
    
    super();
}

/// <summary>
/// Update Integration status. Used when called from a Form
/// </summary>
/// <param name = "_integrationStatus">Integration Status</param>
public void updateIntegrationStatus(METIntegrationStatus _integrationStatus)
{
    ttsbegin;
    this.doUpdateIntegrationStatus(_integrationStatus);
    ttscommit;
}

/// <summary>
/// Update Integration status. Used when called from a Class
/// </summary>
/// <param name = "_integrationStatus">Integration Status</param>
public void doUpdateIntegrationStatus(METIntegrationStatus _integrationStatus)
{
    this.selectForUpdate(true);
    this.IntegrationStatus = _integrationStatus;
    this.update();
}
